import { NextRequest, NextResponse } from 'next/server'
import { Types } from 'mongoose'
import { auth } from '@/lib/auth'
import { connectDB } from '@/lib/db'
import { Vendor } from '@/models/vendor'
import { VendorDeliveryRule } from '@/models/vendor-delivery-rule'
import CampusLocation from '@/models/campus-location'
async function admin(request: NextRequest) { const session = await auth.api.getSession({ headers: request.headers }); return session?.user?.role === 'admin' ? session : null }
export async function GET(request: NextRequest, { params }: { params: Promise<{ id: string }> }) { if (!await admin(request)) return NextResponse.json({ error: 'Forbidden' }, { status: 403 }); const { id } = await params; if (!Types.ObjectId.isValid(id)) return NextResponse.json({ error: 'Invalid vendor.' }, { status: 400 }); await connectDB(); const [parents, rules] = await Promise.all([CampusLocation.find({ parentLocationId: null, active: true }).select('_id name type').sort({ name: 1 }).lean(), VendorDeliveryRule.find({ vendorId: id }).lean()]); const byParent = new Map(rules.map(rule => [String(rule.dropoffParentLocationId), rule])); return NextResponse.json({ destinations: parents.map(parent => { const rule = byParent.get(String(parent._id)); return { parentLocationId: String(parent._id), name: parent.name, enabled: rule?.enabled || false, serviceFee: rule?.serviceFee || null } }) }) }
export async function PATCH(request: NextRequest, { params }: { params: Promise<{ id: string }> }) { const session = await admin(request); const { id } = await params; if (!session) return NextResponse.json({ error: 'Forbidden' }, { status: 403 }); if (!Types.ObjectId.isValid(id)) return NextResponse.json({ error: 'Invalid vendor.' }, { status: 400 }); await connectDB(); const body = await request.json(), destination = String(body.dropoffParentLocationId || ''), enabled = Boolean(body.enabled), serviceFee = Number(body.serviceFee); if (!await Vendor.exists({ _id: id })) return NextResponse.json({ error: 'Vendor not found.' }, { status: 404 }); if (!Types.ObjectId.isValid(destination) || !await CampusLocation.exists({ _id: destination, parentLocationId: null, active: true })) return NextResponse.json({ error: 'Drop-off must be an active parent location.' }, { status: 400 }); if (enabled && (!Number.isInteger(serviceFee) || serviceFee < 1)) return NextResponse.json({ error: 'Enabled coverage needs a whole positive Naira fee.' }, { status: 400 }); await VendorDeliveryRule.findOneAndUpdate({ vendorId: id, dropoffParentLocationId: destination }, { $set: { enabled, ...(enabled ? { serviceFee } : {}), updatedBy: session.user.id } }, { upsert: true, new: true, setDefaultsOnInsert: true }); return NextResponse.json({ ok: true }) }
